INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('mem_piece_tracking', 'memory_visualization', 'Blindfold Piece Tracking', 'Tracking moves without a physical board over 5-10 move sequences without losing piece states.', 1.5, '{"90-100": "Tracks multiple moving pieces across 8+ plies without losing square occupancy.", "70-89": "Maintains position up to 5 moves before needing a position recap.", "50-69": "Loses track of subtle piece displacements after 3 moves.", "0-49": "Visualization breaks down after 1-2 moves; ghost pieces hallucinated."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
