INSERT INTO skills (id, name, description, category, active) VALUES ('negotiation', 'Negotiation', 'Tactical empathy, anchoring, concession management, BATNA preservation, and emotional control.', 'business', true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('neg_anchoring_framing', 'negotiation', 'Anchoring & Framing', 'Setting psychological anchor, framing terms around mutual value, controlling baseline.', 1.2, '{"90-100": "Anchors strategically with objective justification; controls terms of debate.", "70-89": "Reasonable anchor, slight hesitation when counter-anchored.", "50-69": "Accepts counterparty''s hostile anchor without pushback.", "0-49": "Bids against self; makes concessions before counterparty even asks."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('negotiation', 'neg_anchoring_framing', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('neg_concession_tradeoffs', 'negotiation', 'Concession Trading (If-Then)', 'Never giving anything away for free; demanding reciprocal value for every shift.', 1.4, '{"90-100": "Strict ''If we do X, you must do Y'' trade-offs; protects key commercial terms.", "70-89": "Trades concessions well but gives away minor points without equivalent return.", "50-69": "Gives away price or scope unilaterally to be ''polite''.", "0-49": "Total capitulation under minimal pressure."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('negotiation', 'neg_concession_tradeoffs', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('neg_tactical_empathy', 'negotiation', 'Tactical Empathy & Calibrated Questions', 'Using ''How'' and ''What'' calibrated questions; labeling counterpart''s unspoken fears.', 1.1, '{"90-100": "Masterful mirroring and labeling; turns adversary into joint problem-solver.", "70-89": "Good listening; asks productive questions with minor defensiveness.", "50-69": "Interrupts counterparty; focuses only on own demands.", "0-49": "Hostile, antagonistic; creates unnecessary impasse."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('negotiation', 'neg_tactical_empathy', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skills (id, name, description, category, active) VALUES ('problem_solving', 'Problem Solving', 'Systematic decomposition (MECE), root cause identification (5-Whys), and constraint optimization.', 'cognition', true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('prob_mece_decomposition', 'problem_solving', 'MECE Decomposition', 'Mutually Exclusive, Collectively Exhaustive issue trees breaking intractable issues down.', 1.3, '{"90-100": "Flawless issue tree; zero overlap between branches, leaves no blind spots.", "70-89": "Strong decomposition with minor overlap or slight omission.", "50-69": "Messy categorization; confuses symptoms with root causes.", "0-49": "Chaotic, unstructured brainstorming without hierarchy."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('problem_solving', 'prob_mece_decomposition', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('prob_root_cause', 'problem_solving', 'Root Cause Analysis (5-Whys)', 'Drilling past superficial symptoms to uncover underlying systemic failure.', 1.2, '{"90-100": "Penetrates to true systemic root cause; proposes irreversible structural fix.", "70-89": "Finds operational root cause but misses cultural/incentive misalignment.", "50-69": "Fixates on proximate symptom rather than underlying driver.", "0-49": "Applies band-aid to superficial manifestation; problem immediately recurs."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('problem_solving', 'prob_root_cause', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skills (id, name, description, category, active) VALUES ('public_speaking', 'Public Speaking', 'Stage presence, executive opening hook, vocal modulation, audience retention, and closing impact.', 'communication', true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('pub_hook_opening', 'public_speaking', 'Opening Hook & Retention', 'Capturing undivided audience attention within the first 15 seconds without platitudes.', 1.3, '{"90-100": "Electrifying opening story, counter-intuitive insight, or provocative question.", "70-89": "Strong opening with minor conventional pleasantries (''Thank you for having me'').", "50-69": "Generic, polite throat-clearing; audience attention wanes.", "0-49": "Boring administrative monologue; loses room immediately."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('public_speaking', 'pub_hook_opening', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('pub_vocal_variety', 'public_speaking', 'Vocal Modulation & Projection', 'Dynamic volume, pitch variation, deliberate dramatic pauses, resonance.', 1.2, '{"90-100": "Masterful dynamic range; uses quiet pauses to command total silence; energetic peaks.", "70-89": "Good vocal energy with occasional monotone stretches.", "50-69": "Monotone delivery; rushes through critical punchlines.", "0-49": "Mumbles, speaks in low monotone, or sounds robotic and detached."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('public_speaking', 'pub_vocal_variety', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
