INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('sales_discovery', 'sales', 'Discovery Questioning', 'Uncovering budget, decision-making authority, pain intensity, and timeline.', 1.3, '{"90-100": "Deep open-ended questions; diagnoses before prescribing; prospect does 70% of talking.", "70-89": "Good diagnostic flow with minor premature pitching.", "50-69": "Interrogative or superficial; misses core business driver.", "0-49": "Immediately pitches product without understanding prospect''s situation."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('sales', 'sales_discovery', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('sales_objection_handling', 'sales', 'Objection Rebuttal', 'Reframing price, competitor, and timing objections with empathy and economic proof.', 1.4, '{"90-100": "Validates concern, isolates real objection, reframes around ROI and risk.", "70-89": "Answers objection directly but misses deeper underlying hesitation.", "50-69": "Becomes argumentative or offers discounts too early.", "0-49": "Accepts objection passively or capitulates on price."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('sales', 'sales_objection_handling', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO skill_dimensions (id, skill_id, name, description, weight, rubric_criteria) VALUES ('sales_closing', 'sales', 'Closing & Next Steps', 'Securing clear next steps, dates, and commitments without being pushy or passive.', 1.2, '{"90-100": "Clear reciprocal agreement; locks calendar date and agenda for mutual action plan.", "70-89": "Agrees to next meeting but leaves exact date or deliverables open.", "50-69": "Passive ''Let me know if you have questions'' sign-off.", "0-49": "No call-to-action; allows call to fizzle into dead silence."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, weight = EXCLUDED.weight;
INSERT INTO skill_state (skill_id, dimension_id, level, sublevel, score, confidence, trend) VALUES ('sales', 'sales_closing', 1, 1, 50.00, 0.50, 'STABLE') ON CONFLICT (dimension_id) DO NOTHING;
INSERT INTO challenges (id, skill_id, dimension_id, type, title, instructions, constraints, time_limit_seconds, difficulty, rubric) VALUES 
('10000000-0000-0000-0000-000000000001', 'communication', 'comm_clarity', 'EXPLAIN', 'Explain Quantum Computing to a 12-Year-Old', 'Explain quantum superposition and entanglement to a middle-school student using a concrete physical metaphor.', ARRAY['Time limit: 90 seconds', 'Zero mathematical jargon (no qubits, wavefunctions, vectors)', 'Must use a physical everyday analogy'], 90, 65, '[{"dimensionId": "comm_clarity", "name": "Clarity", "weight": 1.2, "passThreshold": 70, "evalPrompt": "Check for absolute simplicity without sacrificing fundamental truth."}]'::jsonb),
('10000000-0000-0000-0000-000000000002', 'entrepreneurship', 'ent_problem_validation', 'ROLEPLAY', 'Cold Discovery on Hostile B2B VP', 'You are speaking with a cynical VP of Operations. They claim their current spreadsheet process works fine and they have no budget.', ARRAY['Do not pitch features', 'Uncover one quantifiable workflow delay', 'Maintain calm consultative posture'], 120, 70, '[{"dimensionId": "ent_problem_validation", "name": "Problem Validation", "weight": 1.3, "passThreshold": 70, "evalPrompt": "Did the user diagnose underlying cost before suggesting a solution?"}]'::jsonb),
('10000000-0000-0000-0000-000000000003', 'chess', 'chess_tactical_depth', 'CHESS_TACTIC', 'The Greek Gift Sacrifice (Bxh7+)', 'White plays Bxh7+ in the classical French defense position. Black plays Kxh7. State the exact 3-move forcing continuation for White and explain why Black cannot defend g7.', ARRAY['State full algebraic notation', 'Explain Black''s best counter-defense', 'Time limit: 60 seconds'], 60, 68, '[{"dimensionId": "chess_tactical_depth", "name": "Tactical Depth", "weight": 1.4, "passThreshold": 75, "evalPrompt": "Verify Ng5+ followed by Qh5+ and mating threats."}]'::jsonb)
